SEE.SampleFiles = {"calculator/calc.c":"/* calc.c: a calculator driven by a table of function pointers.\n   Each entry pairs an operator character with the function that does the work. */\n#include <stdio.h>\n\ndouble add(double a, double b) { return a + b; }\ndouble sub(double a, double b) { return a - b; }\ndouble mul(double a, double b) { return a * b; }\ndouble divide(double a, double b) { return b != 0 ? a / b : 0; }\n\nstruct op {\n    char symbol;\n    double (*fn)(double, double);    /* a pointer to a function taking two doubles */\n};\n\nstatic const struct op ops[] = {\n    { '+', add }, { '-', sub }, { '*', mul }, { '/', divide },\n};\n\nint main(void)\n{\n    double a, b;\n    char c;\n    unsigned i;\n\n    printf(\"type a sum like 6 * 7\\n\");\n    while (scanf(\"%lf %c %lf\", &a, &c, &b) == 3) {\n        for (i = 0; i < sizeof ops / sizeof ops[0]; i++)\n            if (ops[i].symbol == c)\n                printf(\"%g %c %g = %g\\n\", a, c, b, ops[i].fn(a, b));\n    }\n    return 0;\n}\n","const/const.c":"/* const.c: what each const locks.\n   Read every declaration from the name outwards.\n   Take the comment marks off one of the \"error\" lines and build (Ctrl+B) to see the message. */\n#include <stdio.h>\n\nconst int limit = 10;              /* a const global: it lives in read-only data */\n\nint main(void)\n{\n    int n = 1, m = 2;\n    const int *p = &n;             /* pointer to const int: *p is locked */\n    int *const q = &n;             /* const pointer to int: q is locked */\n    const int *const r = &n;       /* both */\n\n    p = &m;                        /* allowed */\n    /* *p = 5;                        error: assignment of read-only location '*p' */\n    *q = 5;                        /* allowed: n becomes 5 */\n    /* q = &m;                        error: assignment of read-only variable 'q' */\n    /* limit = 20;                    error: assignment of read-only variable 'limit' */\n\n    printf(\"n=%d m=%d *p=%d *q=%d *r=%d limit=%d\\n\", n, m, *p, *q, *r, limit);\n    return 0;\n}\n","guess/guess.c":"/* guess.c: guess the number. It reads your guesses from the terminal:\n   type a number and press Enter when the program waits. */\n#include <stdio.h>\n#include <stdlib.h>\n#include <time.h>\n\nint main(void)\n{\n    int secret, guess, tries = 0;\n\n    srand((unsigned)time(NULL));\n    secret = rand() % 100 + 1;\n    printf(\"I am thinking of a number from 1 to 100.\\n\");\n    for (;;) {\n        printf(\"your guess: \");\n        fflush(stdout);              /* show the prompt before waiting for input */\n        if (scanf(\"%d\", &guess) != 1)\n            break;\n        tries++;\n        if (guess < secret)\n            printf(\"higher\\n\");\n        else if (guess > secret)\n            printf(\"lower\\n\");\n        else {\n            printf(\"yes! %d tries\\n\", tries);\n            break;\n        }\n    }\n    return 0;\n}\n","hanoi/hanoi.c":"/* hanoi.c: the towers of Hanoi.\n   Step into the recursion (F11) and watch a new frame for every call;\n   the Variables panel lists them all, and each has its own n, from, to and via. */\n#include <stdio.h>\n\nstatic int moves;\n\nvoid hanoi(int n, char from, char to, char via)\n{\n    if (n == 0)\n        return;\n    hanoi(n - 1, from, via, to);\n    moves++;\n    printf(\"move disc %d from %c to %c\\n\", n, from, to);\n    hanoi(n - 1, via, to, from);\n}\n\nint main(void)\n{\n    hanoi(3, 'A', 'C', 'B');\n    printf(\"%d moves\\n\", moves);\n    return 0;\n}\n","jagged/jagged.c":"/* jagged.c: a triangle of numbers with rows of different lengths.\n   rows lives on the stack; it points to an array of row pointers on the heap,\n   and each of those points to its own block. Step and watch the arrows appear. */\n#include <stdio.h>\n#include <stdlib.h>\n\nint main(void)\n{\n    int n = 5, i, j;\n    int **rows = malloc(n * sizeof *rows);    /* n pointers, one per row */\n\n    for (i = 0; i < n; i++) {\n        rows[i] = malloc((i + 1) * sizeof **rows);    /* row i holds i + 1 numbers */\n        for (j = 0; j <= i; j++)\n            rows[i][j] = (j == 0 || j == i) ? 1 : rows[i - 1][j - 1] + rows[i - 1][j];\n    }\n    for (i = 0; i < n; i++) {\n        for (j = 0; j <= i; j++)\n            printf(\"%d \", rows[i][j]);\n        printf(\"\\n\");\n    }\n    for (i = 0; i < n; i++)\n        free(rows[i]);     /* the rows first ... */\n    free(rows);            /* ... then the array that pointed at them */\n    return 0;\n}\n","linked-list/list.c":"/* list.c: a linked list, built at the front.\n   Every node is a heap block; each next pointer is an arrow to the following node. */\n#include <stdio.h>\n#include <stdlib.h>\n\nstruct node {\n    int value;\n    struct node *next;\n};\n\n/* head is passed by address so push can change the caller's pointer */\nvoid push(struct node **head, int value)\n{\n    struct node *n = malloc(sizeof *n);\n    n->value = value;\n    n->next = *head;\n    *head = n;\n}\n\nvoid free_list(struct node *n)\n{\n    while (n != NULL) {\n        struct node *next = n->next;   /* read next before the node is gone */\n        free(n);\n        n = next;\n    }\n}\n\nint main(void)\n{\n    struct node *head = NULL;\n    struct node *p;\n    int i;\n\n    for (i = 1; i <= 4; i++)\n        push(&head, i * 10);\n    for (p = head; p != NULL; p = p->next)\n        printf(\"%d -> \", p->value);\n    printf(\"NULL\\n\");\n    free_list(head);\n    return 0;\n}\n","notes/notes.c":"/* notes.c: write a file, then read it back.\n   The file goes in /tmp; look for it in the Files panel afterwards. */\n#include <stdio.h>\n\nint main(void)\n{\n    FILE *f;\n    char line[80];\n    int n = 0;\n\n    f = fopen(\"/tmp/notes.txt\", \"w\");\n    if (f == NULL) {\n        perror(\"/tmp/notes.txt\");\n        return 1;\n    }\n    fprintf(f, \"buy milk\\n\");\n    fprintf(f, \"learn pointers\\n\");\n    fprintf(f, \"call home\\n\");\n    fclose(f);\n\n    f = fopen(\"/tmp/notes.txt\", \"r\");\n    if (f == NULL) {\n        perror(\"/tmp/notes.txt\");\n        return 1;\n    }\n    while (fgets(line, sizeof line, f) != NULL)\n        printf(\"%d. %s\", ++n, line);     /* line keeps its \\n */\n    fclose(f);\n    return 0;\n}\n","off-by-one/bug.c":"/* bug.c: find the bug.\n   Run it: See stops it with a memory error. Then debug it (F5), run to the\n   crash, and look at which element of scores the loop was writing.\n   Can you fix the loop condition? */\n#include <stdio.h>\n\nint main(void)\n{\n    int scores[5];\n    int i, total = 0;\n\n    for (i = 0; i <= 5; i++)       /* the bug: <= runs once too many */\n        scores[i] = i * 10;\n    for (i = 0; i < 5; i++)\n        total += scores[i];\n    printf(\"total %d\\n\", total);\n    return 0;\n}\n","padding/padding.c":"/* padding.c: why sizeof a struct is more than the sum of its fields.\n   Open s in the memory picture and point at the gaps between the fields. */\n#include <stdio.h>\n#include <stddef.h>\n\nstruct sample {\n    char c;      /* 1 byte, then 7 bytes of padding so d starts on a multiple of 8 */\n    double d;\n    short s;     /* 2 bytes, then 6 bytes so the whole struct is a multiple of 8 */\n};\n\nstruct packed {\n    double d;    /* largest first: only 2 bytes of padding at the end */\n    short s;\n    char c;\n};\n\nint main(void)\n{\n    struct sample s;\n\n    s.c = 'A';\n    s.d = 3.5;\n    s.s = 7;\n    printf(\"sizeof(struct sample) = %d\\n\", (int)sizeof(struct sample));\n    printf(\"offsets: c %d, d %d, s %d\\n\", (int)offsetof(struct sample, c), (int)offsetof(struct sample, d), (int)offsetof(struct sample, s));\n    printf(\"sizeof(struct packed) = %d\\n\", (int)sizeof(struct packed));\n    printf(\"%c %.1f %d\\n\", s.c, s.d, s.s);\n    return 0;\n}\n","stack-module/main.c":"/* main.c: uses the stack module. See builds every .c file in this folder\n   and links them into one program; stack.h is how main.c knows the names. */\n#include <stdio.h>\n#include \"stack.h\"\n\nint main(void)\n{\n    stack_push(1);\n    stack_push(2);\n    stack_push(3);\n    printf(\"size %d\\n\", stack_size());\n    while (stack_size() > 0)\n        printf(\"popped %d\\n\", stack_pop());\n    return 0;\n}\n","stack-module/stack.c":"/* stack.c: the stack's data is static, so no other file can touch it directly */\n#include \"stack.h\"\n\n#define CAPACITY 16\n\nstatic int items[CAPACITY];   /* static at file level: private to this file */\nstatic int top;\n\nvoid stack_push(int value)\n{\n    if (top < CAPACITY)\n        items[top++] = value;\n}\n\nint stack_pop(void)\n{\n    return top > 0 ? items[--top] : 0;\n}\n\nint stack_size(void)\n{\n    return top;\n}\n","stack-module/stack.h":"/* stack.h: what other files may know about the stack module */\n#ifndef STACK_H\n#define STACK_H\n\nvoid stack_push(int value);\nint stack_pop(void);\nint stack_size(void);\n\n#endif\n","strings/where.c":"/* where.c: the same text in three places.\n   Step to the printf and compare the three in the memory picture. */\n#include <stdio.h>\n#include <string.h>\n#include <stdlib.h>\n\nchar global[] = \"global\";      /* .data: a global array, filled in before main runs */\n\nint main(void)\n{\n    char local[] = \"on the stack\";       /* the literal is copied into main's frame */\n    const char *lit = \"read-only\";       /* points straight at the literal, in .rodata */\n    char *heap = malloc(strlen(lit) + 1);   /* + 1 for the NUL at the end */\n\n    strcpy(heap, lit);                   /* a copy on the heap, which we may change */\n    local[0] = 'O';                      /* fine: our own array */\n    heap[0] = 'R';                       /* fine: our own block */\n    /* lit[0] = 'X'; would crash: string literals cannot be changed */\n\n    printf(\"%s | %s | %s | %s\\n\", global, local, lit, heap);\n    printf(\"addresses: %p %p %p %p\\n\", (void *)global, (void *)local, (void *)lit, (void *)heap);\n    free(heap);\n    return 0;\n}\n","swap/swap.c":"/* swap.c: why swap needs pointers.\n   Debug it (F5) and step into both swaps (F11). Watch the frames:\n   swap_values gets copies of a and b, swap_pointed gets their addresses. */\n#include <stdio.h>\n\nvoid swap_values(int x, int y)\n{\n    int t = x;      /* x and y are this frame's own copies */\n    x = y;\n    y = t;          /* only the copies changed */\n}\n\nvoid swap_pointed(int *x, int *y)\n{\n    int t = *x;     /* follow the arrows back into main's frame */\n    *x = *y;\n    *y = t;         /* main's a and b really change */\n}\n\nint main(void)\n{\n    int a = 1, b = 2;\n\n    swap_values(a, b);\n    printf(\"after swap_values:  a = %d, b = %d\\n\", a, b);\n    swap_pointed(&a, &b);\n    printf(\"after swap_pointed: a = %d, b = %d\\n\", a, b);\n    return 0;\n}\n"};
